// src/pages/Admin/Dashboard.js
import { Outlet, Routes, Route } from 'react-router-dom';
import Home from './Home';

export default function AdminDashboard() {
  return (
    <div>
      <h1>Admin Layout</h1>
      <Routes>
        <Route index element={<Home />} />
      </Routes>
    </div>
  );
}
